code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import deque
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); q.append((ny,nx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            if r1-r0<2 or c1-c0<2: continue
            border={(y,x) for y,x in cells if y in (r0,r1) or x in (c0,c1)}
            if set(cells)==border:
                if all(grid[y][x]==color for y,x in border):
                    for y in range(r0+1,r1):
                        for x in range(c0+1,c1):
                            if grid[y][x]==bg: out[y][x]=7
    return out
'''
